g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "negotiation-ladder",
  "x": 64, "y": 262, "width": 1152, "height": 312,
  "strict_grid": true,
  "column_widths": [300, 480, 372],
  "row_heights": [40, 68, 68, 68, 68],
  "style": {
    "font_family": "Calibri",
    "font_size": 18,
    "header_text": "#BC9E60",
    "body_text": "#FBF8F2",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 12, "right": 12, "top": 4, "bottom": 4},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#BC9E60", "width": 1},
        "bottom": {"style": "solid", "color": "#BC9E60", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Priority", "bold": true, "align": "l"},
    {"text": "Specific request", "bold": true, "align": "l"},
    {"text": "What makes it a concession?", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"text": "Foundation: 8% protection", "bold": true},
      {"text": "Confirm annual compounding, return of contributed capital including fees, and the existing catch-up clause. Preserve stronger existing protection."},
      {"text": "An existing hurdle is not a new concession."}
    ],
    [
      {"text": "1 — Lead with A", "bold": true},
      {"text": "8% preferred return, no GP catch-up, 20% carry."},
      {"text": "First economic choice at the assigned 20% growth; +$17.92m if the reference hurdle already exists."}
    ],
    [
      {"text": "2 — If A is refused, pursue B", "bold": true},
      {"text": "Retain the 8% preferred return; full catch-up targeting 15%; 15% carry."},
      {"text": "Acceptable alternative; +$16.59m on the same conditional comparison."}
    ],
    [
      {"text": "Fallback request where absent", "bold": true},
      {"text": "8% preferred return, full catch-up, 20% carry."},
      {"text": "Adds protection only if not already provided; otherwise the status quo."}
    ]
  ]
}
